sys_script_include.script:
var AcordRenderer = Class.create();

// value_map schemes used for ACORD code lists (internal token -> ACORD code)
AcordRenderer.SCHEME = {
    LOB: 'acord_lob_code',
    LIMIT: 'acord_limit_applies_to',
    DEDUCTIBLE: 'acord_deductible_applies_to',
    ROLE: 'acord_party_role'
};

AcordRenderer.prototype = {

    initialize: function () {
        this.values = new ValueMapper();
    },

    // type: aggregate key; doc: AggregateSerializer output. Returns ACORD-aligned XML.
    render: function (type, doc) {
        var d = doc && doc.data ? doc.data : {};
        var x = [];
        x.push('<?xml version="1.0" encoding="UTF-8"?>');
        x.push('<ACORD>');
        x.push('<InsuranceSvcRq>');
        x.push(this._t('RqUID', gs.generateGUID()));
        x.push('<PolicySyncRq>');
        x.push(this._t('TransactionRequestDt', String(doc.generated_on || '').substring(0, 10)));
        x.push(this._t('CurCd', this._cur(d.currency)));
        if (type === 'policy_version' || type === 'policy')
            this._policy(x, type === 'policy' ? this._currentVersion(d) || d : d, type === 'policy' ? d : null);
        else if (type === 'quote')
            this._quote(x, d);
        else if (type === 'submission')
            this._submission(x, d);
        else
            this._product(x, d);
        x.push('</PolicySyncRq>');
        x.push('</InsuranceSvcRq>');
        x.push('</ACORD>');
        return x.join('\n');
    },

    _policy: function (x, v, header) {
        var parties = v.parties || [];
        this._parties(x, parties, 'party_role', 'account');
        x.push('<CommlPolicy>');
        x.push(this._t('PolicyNumber', header ? header.policy_number : (v.policy ? v.policy.display : '')));
        x.push(this._t('LOBCd', this._lob(v.business_line, v.line_of_business)));
        x.push('<ContractTerm>' + this._t('EffectiveDt', v.transaction_effective_date) + '</ContractTerm>');
        x.push('<CurrentTermAmt>' + this._t('Amt', v.total_premium) + '</CurrentTermAmt>');
        x.push(this._t('PolicyStatusCd', v.status));
        x.push('</CommlPolicy>');
        var risks = v.risks || [];
        for (var i = 0; i < risks.length; i++) {
            x.push('<Location id="L' + (i + 1) + '">');
            x.push(this._t('ItemIdInfo', risks[i].insurable_object ? risks[i].insurable_object.display : risks[i].name));
            x.push(this._t('ConstructionCd', risks[i].construction));
            x.push('<TotalInsurableValueAmt>' + this._t('Amt', risks[i].sum_insured) + '</TotalInsurableValueAmt>');
            x.push('</Location>');
        }
        this._coverages(x, v.coverages || [], 'terms', 'selected_value', 'coverage');
    },

    _quote: function (x, q) {
        x.push('<CommlPolicy>');
        x.push(this._t('QuoteInfo', q.quote_number));
        x.push('<ContractTerm>' + this._t('EffectiveDt', q.effective_date) + this._t('ExpirationDt', q.expiration_date) + '</ContractTerm>');
        x.push('</CommlPolicy>');
        var opts = q.options || [];
        for (var i = 0; i < opts.length; i++) {
            x.push('<QuoteOption id="O' + (i + 1) + '">');
            x.push(this._t('OptionName', opts[i].name));
            var lines = opts[i].lines || [];
            for (var j = 0; j < lines.length; j++) {
                x.push('<LineOfBusiness>' + this._t('LOBCd', this._lob(lines[j].business_line, lines[j].line_of_business)) +
                    '<FullTermAmt>' + this._t('Amt', lines[j].commercial_premium) + '</FullTermAmt></LineOfBusiness>');
            }
            this._coverages(x, opts[i].coverages || [], 'terms', 'term_value', 'coverage');
            x.push('</QuoteOption>');
        }
    },

    _submission: function (x, s) {
        this._parties(x, s.parties || [], 'role', 'organization');
        x.push('<CommlPolicy>');
        x.push(this._t('LOBCd', this._lob(s.business_line, s.line_of_business)));
        x.push('<ContractTerm>' + this._t('EffectiveDt', s.target_effective_date) + this._t('ExpirationDt', s.target_expiration_date) + '</ContractTerm>');
        x.push('</CommlPolicy>');
        var lines = s.lines || [];
        for (var i = 0; i < lines.length; i++) {
            x.push('<LineOfBusiness>' + this._t('LOBCd', this._lob(lines[i].business_line, lines[i].line_of_business)));
            this._coverages(x, lines[i].coverages || [], 'terms', 'requested_value', 'coverage');
            x.push('</LineOfBusiness>');
        }
    },

    _product: function (x, p) {
        x.push('<ProductInfo>' + this._t('ProductCd', p.product_code) + this._t('ProductDesc', p.product_name) +
            this._t('LOBCd', this._lob(p.business_line, p.line_of_business)) + '</ProductInfo>');
    },

    _parties: function (x, parties, roleField, refField) {
        for (var i = 0; i < parties.length; i++) {
            var p = parties[i];
            var role = String(p[roleField] || '');
            var name = p[refField] ? p[refField].display : (p.name || '');
            var tagName = (role === 'broker' || role === 'producer') ? 'Producer' : 'InsuredOrPrincipal';
            x.push('<' + tagName + '><GeneralPartyInfo><NameInfo><CommlName>' + this._t('CommercialName', name) +
                '</CommlName></NameInfo></GeneralPartyInfo>' +
                (tagName === 'InsuredOrPrincipal' ? '<InsuredOrPrincipalInfo>' + this._t('InsuredOrPrincipalRoleCd', this.values.map(AcordRenderer.SCHEME.ROLE, role, false, true)) + '</InsuredOrPrincipalInfo>' : '') +
                '</' + tagName + '>');
        }
    },

    // Coverage with limits / deductibles at any level; scope rides in ItemIdInfo / StateProvCd.
    _coverages: function (x, coverages, termsKey, valueField, covField) {
        for (var i = 0; i < coverages.length; i++) {
            var c = coverages[i];
            x.push('<CommlCoverage>');
            x.push(this._t('CoverageCd', c[covField] ? c[covField].display : c.name));
            x.push(this._t('CoverageDesc', c.name || c.requested_name));
            if (c.insurable_object)
                x.push(this._t('ItemIdRef', c.insurable_object.display));
            var terms = c[termsKey] || [];
            for (var j = 0; j < terms.length; j++) {
                var t = terms[j];
                var amount = t[valueField] !== undefined ? t[valueField] : (t.selected_value !== undefined ? t.selected_value : t.term_value);
                var type = String(t.term_type || '');
                var tag = type === 'deductible' || type === 'retention' ? 'Deductible' : 'Limit';
                x.push('<' + tag + '>' + (amount !== undefined ? '<FormatCurrencyAmt>' + this._t('Amt', amount) + '</FormatCurrencyAmt>' : '') +
                    (t.percentage !== undefined ? this._t('FormatPct', t.percentage) : '') +
                    this._t(tag === 'Limit' ? 'LimitAppliesToCd' : 'DeductibleAppliesToCd',
                        this.values.map(tag === 'Limit' ? AcordRenderer.SCHEME.LIMIT : AcordRenderer.SCHEME.DEDUCTIBLE, t.limit_basis || type, false, true)) +
                    (t.jurisdiction ? this._t('StateProvCd', t.jurisdiction.display) : '') +
                    (t.cause_of_loss ? this._t('CauseOfLossCd', t.cause_of_loss.display) : '') +
                    '</' + tag + '>');
            }
            x.push('</CommlCoverage>');
        }
    },

    _currentVersion: function (policyDoc) {
        var terms = policyDoc.terms || [];
        for (var i = terms.length - 1; i >= 0; i--) {
            var vs = terms[i].versions || [];
            for (var j = vs.length - 1; j >= 0; j--)
                if (vs[j].is_current) return vs[j];
        }
        return null;
    },

    _lob: function (ref, legacyValue) {
        if (!ref) {
            var code = legacyValue ? this.values.map('legacy_lob', legacyValue, false, false) : '';
            if (!code)
                return '';
            var byCode = new GlideRecord(Constants.TABLE.LINE_OF_BUSINESS);
            byCode.addQuery('code', code);
            byCode.setLimit(1);
            byCode.query();
            return byCode.next() ? String(byCode.getValue('acord_lob_code') || code) : code;
        }
        var gr = new GlideRecord(Constants.TABLE.LINE_OF_BUSINESS);
        if (!gr.get(ref.sys_id || ref))
            return '';
        return String(gr.getValue('acord_lob_code') || gr.getValue('code'));
    },

    _cur: function (c) {
        return c ? String(c).toUpperCase() : '';
    },

    _t: function (tag, v) {
        if (v === undefined || v === null || v === '')
            return '';
        if (typeof v === 'object')
            v = v.display !== undefined ? v.display : JSON.stringify(v);
        return '<' + tag + '>' + String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') + '</' + tag + '>';
    },

    type: 'AcordRenderer'
};
